import { html, nothing, type PropertyValues, type TemplateResult } from 'lit'
import { Check, ChevronDown, Database, Layers } from 'lucide'
import { define } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import { Combobox, type ComboOption } from '@/elements/components/ui/combobox'
import styles from 'virtual:tw'

// ScopeMenu.vue as <conare-scope-menu>: where a search looks: every namespace, or one. The button is the search bar's
// 28px chip (.v2-scope), the namespace in mono once one is picked, a 12px chevron that turns over as it opens. The
// 288px panel lists Every namespace over a hairline, then each namespace with its mark (its app's logo, or `own-mark`
// for a namespace written by API or upload), its name in mono and its size, the pick checked; a filter shows past six.
// `single`: a namespace must be chosen, so there is no Every namespace. It extends <conare-combobox>: `namespaces` is
// Vue's `options` ({ name, documents, logo }), and v-model is `value` with `input` and `change`.
export interface ScopeOption { name: string, documents: number, logo?: string | null }
const compact = new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 })

/**
 * @summary Where a search looks: every namespace, or one.
 * @fires input - The scope changed (read `value`).
 * @fires change - The scope changed (read `value`).
 */
export class ScopeMenu extends Combobox {
	static styles = [Combobox.styles, styles]
	static properties = { ...Combobox.properties, namespaces: { type: Array }, single: { type: Boolean }, ownMark: { attribute: 'own-mark' } }

	/** The namespaces: { name, documents, logo } (a JSON attribute or the property). */
	namespaces: ScopeOption[] = []
	/** A namespace must be chosen: no Every namespace. */
	single = false
	/** The mark for a namespace with no app (written by API or upload). */
	ownMark?: string

	constructor() {
		super()
		this.filter = 'auto'
		this.filterLabel = 'Filter namespaces'
		this.width = '288px'
	}
	protected willUpdate(changed: PropertyValues<this>) {
		super.willUpdate(changed)
		if (changed.has('namespaces') || changed.has('single')) {
			const total = this.namespaces.reduce((a, o) => a + o.documents, 0)
			this.options = [
				...(this.single ? [] : [{ value: '', label: 'Every namespace', hint: compact.format(total), pinned: true }]),
				...this.namespaces.map((o) => ({ value: o.name, label: o.name, hint: compact.format(o.documents) })),
			]
			this.label = this.single ? 'add to' : 'search in'
			this.disabled = !this.namespaces.length
		}
	}
	private logoOf(name: string | number) {
		return this.namespaces.find((o) => o.name === name)?.logo ?? null
	}
	protected triggerClasses() {
		return 'group inline-flex h-control-sm max-md:h-control-touch max-md:text-ui pointer-coarse:h-control-touch pointer-coarse:text-ui cursor-pointer items-center gap-1.5 border border-edge bg-surface-subtle px-2 text-meta text-fg transition-[border-color] duration-120 ease-standard hover:border-edge-focus aria-expanded:border-edge-focus aria-expanded:bg-surface active:enabled:bg-surface-subtle disabled:cursor-not-allowed disabled:text-fg-muted focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-edge-focus'
	}
	protected renderTrigger(): TemplateResult {
		const scope = this.value
		const logo = this.logoOf(scope)
		const label = scope || (this.single ? 'Choose a namespace' : 'every namespace')
		return html`${logo ? html`<img src=${logo} alt="" width="12" height="12" class="size-3 object-contain">` : icon(Database, 'database', { size: 12, strokeWidth: 1.5, class: 'text-fg-muted', attrs: { 'aria-hidden': 'true' } })}<span class="sr-only">${this.single ? 'add to' : 'search in'}</span><span class=${scope ? 'max-w-45 truncate type-code-sm' : 'max-w-45 truncate'}>${label}</span>${icon(ChevronDown, 'chevron-down', { size: 12, strokeWidth: 1.5, class: 'text-fg-muted transition-[rotate] duration-120 ease-out group-aria-expanded:rotate-180 group-aria-expanded:duration-180 motion-reduce:transition-none', attrs: { 'aria-hidden': 'true' } })}`
	}
	protected renderOption(o: ComboOption, selected: boolean): TemplateResult {
		const logo = this.logoOf(o.value)
		const mark = o.pinned
			? icon(Database, 'database', { size: 14, strokeWidth: 1.5, class: 'shrink-0 text-fg-muted', attrs: { 'aria-hidden': 'true' } })
			: logo
				? html`<img src=${logo} alt="" width="14" height="14" class="size-3.5 shrink-0 object-contain">`
				: this.ownMark
					? html`<img src=${this.ownMark} alt="" width="14" height="14" class="size-3.5 shrink-0 object-contain">`
					: icon(Layers, 'layers', { size: 14, strokeWidth: 1.5, class: 'shrink-0 text-fg', attrs: { 'aria-hidden': 'true' } })
		return html`${mark}<span class=${o.pinned ? 'min-w-0 flex-1 truncate' : 'min-w-0 flex-1 truncate type-code-sm'}>${o.label}</span><span class="min-w-10 text-right text-meta text-fg-muted tabular-nums">${o.hint ?? nothing}</span>${icon(Check, 'check', { size: 14, strokeWidth: 1.5, class: selected ? 'shrink-0' : 'shrink-0 invisible', attrs: { 'aria-hidden': 'true' } })}`
	}
	protected renderEmpty(query: string) {
		return `No namespace matches "${query}".`
	}
}

define('scope-menu', ScopeMenu)

import { html, LitElement, nothing, type PropertyValues, type TemplateResult } from 'lit'
import { repeat } from 'lit/directives/repeat.js'
import { Check, ChevronsUpDown, Search } from 'lucide'
import { DsFormElement, define, uid } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import { PopoverController, popoverStyles, type Align, type Side } from '@/elements/lib/popover'
import styles from 'virtual:tw'

// Combobox.vue as <conare-combobox>: a list to pick one option from, with a filter over it: Menu's square panel in a
// hairline, 32px rows with the red square marker on the row the arrows or the pointer are on, the pick checked at the
// end. `filter="auto"` shows the filter past six options, `filter="false"` makes it a plain listbox (<conare-select>).
// `pinned` options stay above a hairline and are never filtered. Arrows, Home and End move, Enter picks, typing filters
// (or, with no filter, jumps to the option it starts), Escape closes and returns focus to the trigger. The panel opens
// in the top layer, flips and stays inside the viewport. v-model is `value` with `input` and `change`; `select` fires
// with the option. Form-associated. Vue's `trigger` and `option` slots are methods a subclass overrides
// (renderTrigger, renderOption), as <conare-select> and <conare-scope-menu> do.
export interface ComboOption { value: string | number, label: string, hint?: string, disabled?: boolean, pinned?: boolean }

/**
 * @summary A list to pick one option from, with a filter over it.
 * @fires input - The pick changed (read `value`).
 * @fires change - The pick changed (read `value`).
 * @fires select - An option was picked (detail: the option).
 */
export class Combobox extends DsFormElement {
	static styles = [DsFormElement.styles, popoverStyles, styles]
	static shadowRootOptions = { ...LitElement.shadowRootOptions, delegatesFocus: true }
	static properties = {
		value: {},
		options: { type: Array },
		label: {},
		placeholder: {},
		filter: { converter: (v: string | null) => (v === 'auto' ? 'auto' : v !== 'false') },
		filterLabel: { attribute: 'filter-label' },
		width: {},
		side: {},
		align: {},
		matchWidth: { type: Boolean, attribute: 'match-width' },
		disabled: { type: Boolean, reflect: true },
		name: {},
		required: { type: Boolean },
		description: { attribute: 'aria-description' },
		query: { state: true },
		active: { state: true },
	}

	value: string | number = ''
	/** { value, label, hint, disabled, pinned } (a JSON attribute or the property). */
	options: ComboOption[] = []
	/** The list's name for assistive tech, on the trigger. */
	label = ''
	placeholder = 'Choose'
	/** true, false (a plain listbox) or "auto" (past six options). */
	filter: boolean | 'auto' = true
	filterLabel = 'Filter'
	/** The panel's width (it is at least the trigger's with match-width). */
	width?: string
	side: Side = 'bottom'
	align: Align = 'start'
	matchWidth = false
	disabled = false
	name?: string
	/** An option must be picked for its form to send. */
	required = false
	/** A hint or error for the trigger (a field sets it). */
	description?: string
	protected query = ''
	protected active = 0
	protected uidBase = uid('combobox')
	protected pop = new PopoverController(this, {
		anchor: () => this.renderRoot.querySelector<HTMLElement>('button[data-trigger]'),
		panel: () => this.renderRoot.querySelector<HTMLElement>('.ds-pop'),
		gap: 4,
	})

	/** The trigger button's classes (Vue's triggerClass); a subclass returns its own. */
	protected triggerClasses() {
		return 'group inline-flex h-control-md w-full min-w-0 cursor-pointer items-center gap-2 border border-edge-strong bg-surface px-2.5 text-left text-ui text-fg outline-none transition-[border-color] duration-120 ease-standard focus-visible:border-edge-focus aria-expanded:border-edge-focus disabled:cursor-not-allowed disabled:text-fg-muted max-md:h-control-touch max-md:text-input pointer-coarse:h-control-touch'
	}
	/** The trigger's content (Vue's `trigger` slot). */
	protected renderTrigger(selected: ComboOption | undefined, _open: boolean): TemplateResult {
		return html`<span class=${selected ? 'min-w-0 flex-1 truncate' : 'min-w-0 flex-1 truncate text-fg-muted'}>${selected?.label ?? this.placeholder}</span>${icon(ChevronsUpDown, 'chevrons-up-down', { size: 12, strokeWidth: 1.5, class: 'shrink-0 text-fg-muted', attrs: { 'aria-hidden': 'true' } })}`
	}
	/** One row's content (Vue's `option` slot). */
	protected renderOption(o: ComboOption, selected: boolean): TemplateResult {
		return html`<span class="min-w-0 flex-1 truncate">${o.label}</span>${o.hint ? html`<span class="min-w-10 text-right text-meta text-fg-muted tabular-nums">${o.hint}</span>` : nothing}${icon(Check, 'check', { size: 14, strokeWidth: 1.5, class: selected ? 'shrink-0' : 'shrink-0 invisible', attrs: { 'aria-hidden': 'true' } })}`
	}
	/** What shows when nothing matches (Vue's `empty` slot). */
	protected renderEmpty(query: string): TemplateResult | string {
		return `Nothing matches "${query}".`
	}
	/** The data-ds of the trigger (a subclass's own name, as Vue's fallthrough attribute gives it). */
	protected triggerName() {
		return (this.constructor as typeof Combobox).dsName
	}

	protected get filtering() {
		return this.filter === 'auto' ? this.options.filter((o) => !o.pinned).length > 6 : this.filter
	}
	protected get selected() {
		return this.options.find((o) => o.value === this.value)
	}
	private get pinned() {
		return this.options.filter((o) => o.pinned)
	}
	private get rest() {
		const q = this.query.trim().toLowerCase()
		const all = this.options.filter((o) => !o.pinned)
		return q ? all.filter((o) => o.label.toLowerCase().includes(q)) : all
	}
	private get visible() {
		return [...this.pinned, ...this.rest]
	}
	private optionId = (i: number) => `${this.uidBase}-${i}`

	private move(to: number, step = 1) {
		const list = this.visible
		const n = list.length
		if (!n) return
		for (let k = 0; k < n; k++) {
			const i = (((to + k * step) % n) + n) % n
			if (!list[i]?.disabled) {
				this.active = i
				void this.updateComplete.then(() => this.renderRoot.querySelector(`#${this.optionId(i)}`)?.scrollIntoView({ block: 'nearest' }))
				return
			}
		}
	}

	private async openList(keyboard: boolean) {
		this.query = ''
		this.pop.configure({ side: this.side, align: this.align, matchWidth: this.matchWidth })
		await this.pop.show({ keyboard })
		const at = this.visible.findIndex((o) => o.value === this.value)
		this.move(at >= 0 ? at : 0)
		await this.updateComplete
		this.renderRoot.querySelector<HTMLElement>(this.filtering ? 'input[role="combobox"]' : '[role="listbox"]')?.focus({ preventScroll: true })
	}
	private pick(o: ComboOption | undefined, keyboard: boolean) {
		if (!o || o.disabled) return
		this.commit(o.value)
		this.emit('select', o)
		this.pop.hide(true, keyboard)
	}
	private onTrigger = (event: MouseEvent) => {
		if (this.pop.open) this.pop.hide(false, event.detail === 0)
		else void this.openList(event.detail === 0)
	}
	private onTriggerKey = (event: KeyboardEvent) => {
		if ((event.key === 'ArrowDown' || event.key === 'ArrowUp') && !this.pop.open) {
			event.preventDefault()
			void this.openList(true)
		}
	}
	// With no filter, typing jumps to the option that starts with what was typed in the last half second.
	private typed = ''
	private typedAt = 0
	private onKey = (event: KeyboardEvent) => {
		const k = event.key
		const list = this.visible
		if (k === 'ArrowDown' || k === 'ArrowUp') {
			event.preventDefault()
			this.move(this.active + (k === 'ArrowDown' ? 1 : -1), k === 'ArrowDown' ? 1 : -1)
		} else if ((k === 'Home' || k === 'End') && !this.filtering) {
			event.preventDefault()
			this.move(k === 'Home' ? 0 : list.length - 1, k === 'Home' ? 1 : -1)
		} else if (k === 'Enter' || (k === ' ' && !this.filtering)) {
			event.preventDefault()
			this.pick(list[this.active], true)
		} else if (!this.filtering && k.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey) {
			const now = Date.now()
			this.typed = now - this.typedAt > 500 ? k.toLowerCase() : this.typed + k.toLowerCase()
			this.typedAt = now
			const i = list.findIndex((o) => !o.disabled && o.label.toLowerCase().startsWith(this.typed))
			if (i >= 0) this.move(i)
		}
	}
	private onQuery = (event: Event) => {
		this.query = (event.target as HTMLInputElement).value
		this.move(0)
	}

	// No native control: a required list with no pick is missing its value, as a required select is.
	syncValidity() {
		this.setMissing(this.required && (this.value === '' || this.value === null || this.value === undefined), 'select', this.renderRoot.querySelector<HTMLElement>('button[data-trigger]'))
	}
	protected updated(changed: PropertyValues) {
		super.updated(changed)
		if (changed.has('value')) this.internals.setFormValue(String(this.value ?? ''))
	}
	render() {
		const open = this.pop.open
		const list = this.visible
		const pinned = this.pinned
		const rest = this.rest
		const activeId = open && list.length ? this.optionId(this.active) : undefined
		const listId = `${this.uidBase}-list`
		const filtering = this.filtering
		return html`<button data-ds=${this.triggerName()} data-trigger type="button" class=${this.triggerClasses()} aria-haspopup="listbox" aria-expanded=${String(open)} aria-controls=${open ? listId : nothing} aria-label=${this.label} aria-description=${this.description ?? nothing} ?disabled=${this.inactive} @click=${this.onTrigger} @keydown=${this.onTriggerKey}>${this.renderTrigger(this.selected, open)}</button>${this.pop.rendered
			? html`<div data-ds="combobox" popover="manual" class="ds-pop flex flex-col p-1" data-side=${this.pop.pos.side} ?data-instant=${this.pop.instant} ?data-placed=${this.pop.pos.placed} style=${this.pop.style(this.width ? `width: ${this.width}` : '')} @focusout=${this.pop.onFocusOut}>
				${filtering
					? html`<label class="relative mb-1 block">${icon(Search, 'search', { size: 12, strokeWidth: 1.5, class: 'pointer-events-none absolute top-1/2 left-2.5 -translate-y-1/2 text-fg-muted', attrs: { 'aria-hidden': 'true' } })}<input .value=${this.query} class="h-control-sm w-full border border-edge-strong bg-surface pr-2.5 pl-7 text-meta text-fg outline-none transition-[border-color] duration-120 ease-standard placeholder:text-fg-muted focus:border-edge-focus max-md:h-control-touch max-md:text-input" role="combobox" aria-label=${this.filterLabel} placeholder=${this.filterLabel} aria-autocomplete="list" aria-expanded="true" aria-controls=${listId} aria-activedescendant=${activeId ?? nothing} autocomplete="off" spellcheck="false" @input=${this.onQuery} @keydown=${this.onKey}></label>`
					: nothing}
				<div id=${listId} role="listbox" aria-label=${this.label} tabindex=${filtering ? '-1' : '0'} aria-activedescendant=${!filtering && activeId ? activeId : nothing} class="fade-y flex max-h-65 flex-col overflow-y-auto outline-none" @keydown=${this.onKey}>
					${repeat(list, (o) => `${o.pinned ? 'p' : 'o'}-${o.value}`, (o, i) => html`${i === pinned.length && pinned.length && rest.length ? html`<div class="-mx-1 my-1 h-px shrink-0 bg-edge" role="separator"></div>` : nothing}<div id=${this.optionId(i)} role="option" class="ds-option" aria-selected=${String(o.value === this.value)} aria-disabled=${o.disabled ? 'true' : nothing} ?data-active=${i === this.active} @pointermove=${() => { if (!o.disabled) this.active = i }} @mousedown=${(e: Event) => e.preventDefault()} @click=${() => this.pick(o, false)}>${this.renderOption(o, o.value === this.value)}</div>`)}
					${!rest.length && this.query ? html`<p class="px-3.5 py-2 type-meta text-fg-muted">${this.renderEmpty(this.query)}</p>` : nothing}
				</div>
			</div>`
			: nothing}`
	}
}

define('combobox', Combobox)

/* Combobox.vue's <style>, as it is. */
/* A row of a listbox: Menu's row (console2.css .v2-menu-item). The highlight follows the arrows and the pointer alike,
   as in the command palette, so hover itself draws nothing. */
.ds-option { position: relative; display: flex; height: var(--ds-size-control-md); flex-shrink: 0; align-items: center; gap: var(--ds-space-md); padding: 0 10px 0 14px; color: var(--ds-color-fg); font-size: var(--ds-text-ui); cursor: pointer; transition: background-color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-option::before { position: absolute; top: 50%; left: 5px; width: 4px; height: 4px; margin-top: -2px; background: var(--ds-color-edge-accent); content: ""; opacity: 0; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-option[data-active] { background: var(--ds-color-surface-subtle); }
.ds-option[data-active]::before { opacity: 1; }
.ds-option[aria-disabled="true"] { color: var(--ds-color-fg-muted); cursor: not-allowed; }
@media (pointer: coarse), (max-width: 767px) { .ds-option { height: auto; min-height: 44px; } }

import { html, type TemplateResult } from 'lit'
import { ChevronDown } from 'lucide'
import { define } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import { Combobox, type ComboOption } from '@/elements/components/ui/combobox'
import styles from 'virtual:tw'

// Select.vue as <conare-select>: pick one of a few options in a form: the 32px field (a #C3C1BF hairline that turns ink
// on focus and while open) with a 12px chevron that turns over as it opens, and a listbox on Menu's square panel at
// least as wide as the field, the pick checked. No filter: typing jumps to the option it starts. Arrows, Home, End,
// Enter, Escape (<conare-combobox>, which it extends). v-model is `value` with `input` and `change`. Form-associated.

/**
 * @summary Pick one of a few options in a form.
 * @fires input - The pick changed (read `value`).
 * @fires change - The pick changed (read `value`).
 */
export class Select extends Combobox {
	static styles = [Combobox.styles, styles]

	constructor() {
		super()
		this.filter = false
		this.matchWidth = true
	}
	protected renderTrigger(selected: ComboOption | undefined): TemplateResult {
		return html`<span class=${selected ? 'min-w-0 flex-1 truncate' : 'min-w-0 flex-1 truncate text-fg-muted'}>${selected?.label ?? this.placeholder}</span>${icon(ChevronDown, 'chevron-down', { size: 12, strokeWidth: 1.5, class: 'shrink-0 text-fg-muted transition-[rotate] duration-120 ease-out group-aria-expanded:rotate-180 group-aria-expanded:duration-180 motion-reduce:transition-none', attrs: { 'aria-hidden': 'true' } })}`
	}
}

define('select', Select)
